package build

import (
	"fmt"
	"io"
	"regexp"
	"strings"
	"time"
)

var phaseBoundary = regexp.MustCompile(`^kogen: (checking .+ before the Build changes anything|verifying \(pass [0-9]+\)|pass [0-9]+: .*|reviewing \(review [0-9]+.*|review [0-9]+: .*|committing)$`)

// phaseLine decorates only phase boundaries, never tool progress or diagnostics.
func (b *Attempt) phaseLine(line string) string {
	if phaseBoundary.MatchString(line) {
		return fmt.Sprintf("%s (%d s)", line, b.elapsed()/time.Second)
	}
	return line
}

type phaseProgressWriter struct {
	b   *Attempt
	out io.Writer
}

func (w phaseProgressWriter) Write(p []byte) (int, error) {
	line := string(p)
	if strings.HasSuffix(line, "\n") {
		line = w.b.phaseLine(strings.TrimSuffix(line, "\n")) + "\n"
	}
	n, err := io.WriteString(w.out, line)
	if err != nil {
		return 0, err
	}
	if n != len(line) {
		return 0, io.ErrShortWrite
	}
	return len(p), nil
}

// timePhaseProgress keeps the original session and restores its writer on return.
func (b *Attempt) timePhaseProgress() func() {
	out := b.s.Stderr
	b.s.Stderr = phaseProgressWriter{b, out}
	return func() { b.s.Stderr = out }
}

